import React, { useEffect, useRef, useCallback } from "react";

// Leaflet загружается через CDN в index.html
const L = window.L;

const WMO_EMOJI = {
  Clear: "☀️", Clouds: "☁️", Rain: "🌧️",
  Drizzle: "🌦️", Thunderstorm: "⛈️", Snow: "❄️", Mist: "🌫️",
};

export default function WeatherMap({ weather, onCityChange }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerRef = useRef(null);

  // Reverse geocode lat/lon → city name через Open-Meteo geocoding
  const reverseGeocode = useCallback(async (lat, lon) => {
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json&accept-language=ru`
      );
      const data = await res.json();
      const addr = data.address;
      return (
        addr.city || addr.town || addr.village ||
        addr.county || addr.state || "Неизвестно"
      );
    } catch {
      return null;
    }
  }, []);

  // Init map once
  useEffect(() => {
    if (mapInstanceRef.current || !L) return;

    const map = L.map(mapRef.current, {
      center: [55.75, 37.62],
      zoom: 5,
      zoomControl: true,
    });

    // Dark tile layer (CartoDB Dark Matter)
    L.tileLayer(
      "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",
      {
        attribution: "© OpenStreetMap © CARTO",
        subdomains: "abcd",
        maxZoom: 19,
      }
    ).addTo(map);

    // Click → reverse geocode → fetch weather
    map.on("click", async (e) => {
      const { lat, lng } = e.latlng;
      const cityName = await reverseGeocode(lat, lng);
      if (cityName) onCityChange(cityName);
    });

    mapInstanceRef.current = map;

    return () => {
      map.remove();
      mapInstanceRef.current = null;
    };
  }, [reverseGeocode, onCityChange]);

  // Update marker when weather changes
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!map || !weather || !L) return;

    // We need coordinates — fetch from geocoding
    fetch(
      `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(weather.city)}&count=1`
    )
      .then((r) => r.json())
      .then((data) => {
        const r = data.results?.[0];
        if (!r) return;
        const { latitude: lat, longitude: lon } = r;

        // Remove old marker
        if (markerRef.current) {
          markerRef.current.remove();
          markerRef.current = null;
        }

        // Custom HTML icon
        const emoji = WMO_EMOJI[weather.weather_main] || "🌤️";
        const icon = L.divIcon({
          className: "",
          html: `
            <div class="map-marker">
              <div class="map-marker-bubble">
                <span class="map-marker-emoji">${emoji}</span>
                <span class="map-marker-temp">${weather.temp}°</span>
              </div>
              <div class="map-marker-city">${weather.city}</div>
              <div class="map-marker-pin"></div>
            </div>
          `,
          iconAnchor: [50, 80],
          iconSize: [100, 80],
        });

        const marker = L.marker([lat, lon], { icon })
          .addTo(map)
          .bindPopup(
            `<div class="map-popup">
              <div class="popup-header">${emoji} ${weather.city}, ${weather.country}</div>
              <div class="popup-temp">${weather.temp}°C</div>
              <div class="popup-desc">${weather.description}</div>
              <div class="popup-stats">
                <span>💧 ${weather.humidity}%</span>
                <span>💨 ${weather.wind_speed} м/с</span>
                <span>📊 ${weather.pressure} гПа</span>
              </div>
            </div>`,
            { className: "custom-popup" }
          )
          .openPopup();

        markerRef.current = marker;
        map.flyTo([lat, lon], 8, { duration: 1.2 });
      });
  }, [weather]);

  return (
    <div className="glass-card map-section">
      <h2 className="section-title">🗺️ Карта</h2>
      <p className="map-hint">Кликни по карте чтобы посмотреть погоду в любом месте</p>
      <div ref={mapRef} className="map-container" />
    </div>
  );
}
